import React from 'react';
import classes from './HeroSection.module.css';

import HeroImage from '../../assets/hero-gadgets.jpg'; 

const SHOP_HEADING = 'Майбутнє Технологій у GadgetStore'; 
const SHOP_DESCRIPTION = 'Ми ретельно відбираємо преміальну електроніку та інноваційні аксесуари. Обирайте якість, дизайн та найновіші можливості для вашого сучасного життя.';

export default function HeroSection() {
  return (
    <section className={classes.hero}>
      <div className={classes.imageBox}>
        <img 
          src={HeroImage} 
          alt="Premium Gadgets Selection" 
          className={classes.heroImage}
        />
      </div>
      <div className={classes.content}>
        <h2 className={classes.heading}>{SHOP_HEADING}</h2>
        <p className={classes.text}>{SHOP_DESCRIPTION}</p>
      </div>
    </section>
  );
}
